(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const jsClick = (x, y) => {
    const el = document.elementFromPoint(x, y);
    if (!el) return false;
    const opts = { bubbles: true, cancelable: true, view: window, clientX: x, clientY: y, button: 0 };
    for (const type of ['pointerdown','mousedown','pointerup','mouseup','click']) el.dispatchEvent(new MouseEvent(type, opts));
    return true;
  };
  const post = JSON.parse(localStorage.getItem('mf_post') || '{}');
  if (!post.text) { localStorage.setItem('mf_done', 'error:no-data'); automaNextBlock({ success: false }); return; }
  localStorage.setItem('mf_composer_ready', '0');
  localStorage.setItem('mf_content_ready', '0');
  localStorage.setItem('mf_done', '');

  // 1) 打开发布框（多语言入口）
  let opened = false;
  for (let i = 0; i < 30 && !opened; i++) {
    const btn = [...document.querySelectorAll('[role=button]')].find((e) => {
      const t = (e.textContent || '').trim();
      const r = e.getBoundingClientRect();
      return (t.includes('分享你的新鲜事') || t.includes('分享想法') || t.includes("What's on your mind") || t.includes('무슨 생각을') || t.includes('게시물 만들기') || t.includes('A cosa stai pensando') || t.includes('Crea post')) && r.width > 100 && r.width < 900 && r.bottom > 0 && r.top < innerHeight;
    });
    if (btn) { const r = btn.getBoundingClientRect(); jsClick(r.x + r.width / 2, r.y + r.height / 2); }
    await sleep(700);
    opened = !!document.querySelector('div[contenteditable=true]');
  }
  if (!opened) { localStorage.setItem('mf_done', 'error:composer'); automaNextBlock({ success: false }); return; }
  localStorage.setItem('mf_composer_ready', '1');

  // 2) 等编排脚本注入图片+文本（最长 120 秒）
  for (let i = 0; i < 120; i++) {
    if (localStorage.getItem('mf_content_ready') === '1') break;
    await sleep(1000);
  }
  if (localStorage.getItem('mf_content_ready') !== '1') { localStorage.setItem('mf_done', 'error:content-timeout'); automaNextBlock({ success: false }); return; }

  // 3) 设公开（多语言：中/英/韩/意）
  for (let attempt = 0; attempt < 3; attempt++) {
    const priv = [...document.querySelectorAll('[role=dialog] div[role=button]')].find((e) => {
      const a = (e.getAttribute('aria-label') || '');
      const r = e.getBoundingClientRect();
      return /^(编辑隐私设置|Edit privacy|공개 범위|Modifica la privacy)/.test(a) && r.bottom > 0 && r.top < innerHeight && r.width > 20;
    });
    if (priv) { const r = priv.getBoundingClientRect(); jsClick(r.x + r.width / 2, r.y + r.height / 2); await sleep(1200); }
    const pubRow = [...document.querySelectorAll('[role=dialog] div')].find((e) => {
      const t = (e.textContent || '').trim();
      const r = e.getBoundingClientRect();
      return /^(公开|Public|전체 공개|Pubblico|Tutti)/.test(t) && r.width > 300 && r.height > 40 && r.height < 200;
    });
    if (pubRow) {
      const dot = [...pubRow.querySelectorAll('div, span')].find((d) => { const dr = d.getBoundingClientRect(); return dr.width >= 20 && dr.width <= 40 && dr.height >= 20 && dr.height <= 40 && dr.x >= 0 && dr.x < innerWidth; });
      const target = dot || pubRow;
      const r = target.getBoundingClientRect();
      jsClick(r.x + r.width / 2, r.y + r.height / 2);
      await sleep(800);
    }
    const doneBtn = [...document.querySelectorAll('[role=dialog] div[role=button]')].find((e) => {
      const a = (e.getAttribute('aria-label') || '');
      const t = (e.textContent || '').trim();
      const r = e.getBoundingClientRect();
      return (/^(完成|Done|완료|Fine|Fatto)/.test(a) || /완료/.test(a) || /^(完成|Done|완료|Fine|Fatto)/.test(t)) && r.bottom > 0 && r.top < innerHeight && r.width > 30;
    });
    if (doneBtn) { const r = doneBtn.getBoundingClientRect(); jsClick(r.x + r.width / 2, r.y + r.height / 2); await sleep(1200); }
    const label = [...document.querySelectorAll('div[role=button]')].find((e) => /^(编辑隐私设置|Edit privacy|공개 범위|Modifica la privacy)/.test(e.getAttribute('aria-label') || ''));
    if (label && /分享对象：公开|Shared with: Public|전체 공개|Pubblico|Tutti/.test(label.getAttribute('aria-label') || '')) break;
  }

  // 4) 点发帖（多语言，过滤禁用副本）
  let posted = false;
  for (let attempt = 0; attempt < 3 && !posted; attempt++) {
    const btn = [...document.querySelectorAll('[role=dialog] div[role=button]')].filter((e) => {
      const t = (e.textContent || '').trim();
      const a = (e.getAttribute('aria-label') || '');
      const r = e.getBoundingClientRect();
      return (/^(发帖|Post|게시|Pubblica|Publicar|发布)$/.test(t) || /^(发帖|Post|게시|Pubblica|Publicar|发布)$/.test(a)) && r.bottom > 0 && r.top < innerHeight && r.width > 30 && e.getAttribute('aria-disabled') !== 'true';
    }).sort((a, b) => b.getBoundingClientRect().top - a.getBoundingClientRect().top)[0];
    if (btn) { const r = btn.getBoundingClientRect(); jsClick(r.x + r.width / 2, r.y + r.height / 2); }
    await sleep(3500);
    const closed = ![...document.querySelectorAll('[role=dialog]')].some((d) => d.getBoundingClientRect().width > 300 && d.querySelector('div[contenteditable=true]'));
    if (closed) posted = true;
  }

  localStorage.setItem('mf_done', posted ? 'published' : 'error:post');
  automaNextBlock({ success: posted });
})()
